inputs = ['bbdecc', 'yeih', 'kea', 'hxz', 'vaaew']
outputs = ['bbdecc', 'yecyh', 'kev', 'hxz', 'vvevehj']

# Analyze each transformation
print("Detailed analysis:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    if inp != outp:
        print(f"Index {i}: '{inp}' -> '{outp}'")
        # Find differences
        min_len = min(len(inp), len(outp))
        diff_positions = []
        for j in range(min_len):
            if inp[j] != outp[j]:
                diff_positions.append((j, inp[j], outp[j]))
        if len(inp) != len(outp):
            if len(inp) > len(outp):
                diff_positions.append((len(outp), inp[len(outp):], ''))
            else:
                diff_positions.append((len(inp), '', outp[len(inp):]))
        print(f"  Differences: {diff_positions}")
    else:
        print(f"Index {i}: No change")
    print()

